import java.util.*;

class Solution {
    public void sortColors(int[] flags) {
        int low = 0, mid = 0, high = flags.length - 1;
        while (mid <= high) {
            if (flags[mid] == 0) {
                swap(flags, low++, mid++);   // 0 goes to the front
            } else if (flags[mid] == 1) {
                mid++;                       // 1 stays in the middle
            } else {
                swap(flags, mid, high--);    // 2 goes to the back; recheck flags[mid]
            }
        }
    }

    private void swap(int[] a, int i, int j) {
        int t = a[i]; a[i] = a[j]; a[j] = t;
    }
}

